 void symbol(juce::Graphics& g,juce::Colour colour){using namespace juce;Graphics::ScopedSaveState state(g);g.addTransform(AffineTransform::translation(2.f,getHeight()*.5f-33.f));g.setColour(nd::colour(colour.withAlpha(.8f)));Path shape;float cx=99,cy=36;
  if(entry.type==16){shape.startNewSubPath(61,49);for(int i=0;i<8;++i){float x=61+i*10.f,y=i%2?49.f:24.f;shape.lineTo(x,y);shape.lineTo(x+10,y);}g.strokePath(shape,PathStrokeType(nd::number("stroke",1.8f)));}
  else if(entry.type==11){for(int i=0;i<3;++i){float radius=15+i*8;Path arc;arc.addCentredArc(cx,cy+6,radius,radius*.7f,0,-1.2f,1.2f,true);g.strokePath(arc,PathStrokeType(nd::number("stroke",1.5f)));}g.drawHorizontalLine(48,76,122);}
  else if(entry.type==3){for(int k=0;k<12;++k){float amplitude=(k==0?25:std::exp(-k*.18f)*(k%2?16:23));g.drawVerticalLine(65+k*6,cy-amplitude*.5f,cy+amplitude*.5f);}}
  else if(entry.type>=12&&entry.type<=14){int bands=entry.type==13?3:2;g.drawLine(62,cy,89,cy,1.5f);for(int i=0;i<bands;++i){float y=cy+(i-(bands-1)*.5f)*19;shape.startNewSubPath(89,cy);shape.lineTo(109,y);shape.lineTo(136,y);}g.strokePath(shape,PathStrokeType(nd::number("stroke",1.5f)));}
  else if(entry.type==15){for(int k=0;k<3;++k){float x=78+k*21,y=29+k*6;g.drawVerticalLine((int)x,21,53);g.fillRoundedRectangle(x-5,y-2,10,4,nd::number("radius",1));}}
  else if(entry.type==2||entry.type==6||entry.type==7){shape.startNewSubPath(62,49);if(entry.type==2){shape.lineTo(98,30);shape.lineTo(137,21);}else if(entry.type==7){shape.cubicTo(98,19,109,19,116,34);shape.lineTo(138,47);}else{shape.cubicTo(86,48,91,16,103,27);shape.cubicTo(113,47,122,44,137,28);}g.strokePath(shape,PathStrokeType(nd::number("stroke",1.8f)));}
  else if(entry.type==4){for(int k=0;k<4;++k){g.setColour(nd::colour(colour.withAlpha(.95f-k*.19f)));g.drawRoundedRectangle(65.f+k*18,24.f+k*3,12,24-k*4.f,2,1.5f);}}
  else {int count=entry.type==1||entry.type==9||entry.type==10?2:1;for(int k=0;k<count;++k){Path wave;for(int i=0;i<78;++i){float t=i/77.f,v=std::sin(t*MathConstants<float>::twoPi*2+k*.8f);if(entry.type==5)v=jlimit(-.7f,.7f,v*1.7f);float x=61+i,y=cy-v*12;if(i==0)wave.startNewSubPath(x,y);else wave.lineTo(x,y);}g.setColour(nd::colour(colour.withAlpha(k==0?.85f:.4f)));g.strokePath(wave,PathStrokeType(nd::number("stroke",1.6f)));}}
 }
public:
 std::function<void(int)> onLoadIR;
 FxRow(SynthProcessor& processor,FxEntry e):p(processor),entry(std::move(e)),meter(processor,entry.slot,fxAccent(fxDefinitions()[(size_t)entry.type].name)){using namespace juce;addAndMakeVisible(meter);setComponentID("fx-module:"+String(entry.slot));const auto& def=fxDefinitions()[(size_t)entry.type];power.accent=fxAccent(def.name);if(hasFxGraph(entry.type)){graph=std::make_unique<FxGraph>(p,entry,fxAccent(def.name));addAndMakeVisible(*graph);}for(auto* c:std::array<Component*,4>{&power,&up,&down,&remove})addAndMakeVisible(c);power.setComponentID("fx-bypass:"+String(entry.slot));power.getProperties().set("parameterIndex",p.state.getParameter(fxId(entry.slot,"enabled"))->getParameterIndex());powerLink=std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.state,fxId(entry.slot,"enabled"),power);up.getProperties().set("rackRailIcon","up");down.getProperties().set("rackRailIcon","down");remove.getProperties().set("rackRailIcon","remove");for(auto* button:{&up,&down,&remove})button->setMouseCursor(MouseCursor::PointingHandCursor);up.setTooltip("Move effect earlier");down.setTooltip("Move effect later");remove.setTooltip("Remove effect from rack");up.onClick=[this]{p.moveFx(entry.slot,-1);};down.onClick=[this]{p.moveFx(entry.slot,1);};remove.onClick=[this]{p.removeFx(entry.slot);};for(int i=0;i<(int)def.controls.size();++i){auto* knob=knobs.add(new FxKnob(p,entry.slot,i,def));addAndMakeVisible(knob);}auto* wet=knobs.add(new FxKnob(p,entry.slot,-1,def));wet->setComponentID("fx-mix:"+String(entry.slot));addAndMakeVisible(wet);if(entry.type==3){addAndMakeVisible(ir);ir.setTooltip("Load WAV/AIFF/FLAC impulse response. Up to 4 seconds processed; embedded in the preset. Maximum file size 16 MB.");ir.setButtonText(entry.irName.isEmpty()?"LOAD IR / Built-in Room":entry.irName);ir.onClick=[this]{if(onLoadIR)onLoadIR(entry.slot);};}}
 static int preferredHeight(int type){return hasFxGraph(type)?244:120;}
 void refreshVisual(){power.setTooltip(p.value(fxId(entry.slot,"enabled"))>.5f?"Effect active - click to bypass":"Bypass active - click to enable effect");if(graph){graph->setAlpha(p.value(fxId(entry.slot,"enabled"))>.5f?1.f:.35f);graph->repaint();}if(entry.type==5)knobs[1]->slider.updateText();repaint();}
 void resized()override{int middle=180,right=getWidth()-218,area=right-middle-9,count=knobs.size()-1;int base=(getHeight()-120)/2;int top=graph?132:entry.type==3?32:12,height=graph?96:getHeight()-top-12;if(graph)graph->setBounds(middle+4,8,area-8,114);for(int i=0;i<count;++i){int cell=area/count,w=juce::jmin(94,cell-3);knobs[i]->setBounds(middle+i*cell+(cell-w)/2,top,w,height);}knobs.getLast()->setBounds(getWidth()-214,base+12,70,96);meter.setBounds(getWidth()-139,base+10,72,100);power.setBounds(getWidth()-23,getHeight()/2-10,20,20);up.setBounds(4,getHeight()/2-23,18,20);down.setBounds(4,getHeight()/2+3,18,20);remove.setBounds(getWidth()-22,6,18,20);if(entry.type==3)ir.setBounds(middle+8,10,area-16,20);}
 void paint(juce::Graphics& g)override{nd::Scope suitScope("rack");using namespace juce;auto r=getLocalBounds().toFloat().reduced(.5f);auto colour=p.value(fxId(entry.slot,"enabled"))>.5f?fxAccent(fxDefinitions()[(size_t)entry.type].name):Colour(0xff718393);
  // Metal front plate and mounting ears are part of the FX rack's hardware design.
  g.setGradientFill(ColourGradient(nd::colour(Colour(0xff3b4c59)),0,0,nd::colour(Colour(0xff202d38)),0,r.getBottom(),false));g.fillRoundedRectangle(r,nd::number("radius",4));
  for(float x:{0.f,(float)getWidth()-26}){Rectangle<float> ear(x,0,26,(float)getHeight());g.setGradientFill(ColourGradient(nd::colour(Colour(0xff354b5c)),x,0,nd::colour(Colour(0xff6a7e8d)),x+11,0,false));g.fillRect(ear);g.setColour(nd::colour(nd::colour(Colour(0xff0c1822))));g.drawVerticalLine(roundToInt(x+25),1,(float)getHeight()-1);g.setColour(nd::colour(nd::colour(Colour(0xffa9bccb)).withAlpha(.35f)));g.drawVerticalLine(roundToInt(x+1),1,(float)getHeight()-1);}
  g.setColour(nd::colour(nd::colour(Colour(0xff101c25)).withAlpha(.42f)));g.fillRect(26,0,150,28);g.setColour(nd::colour(nd::colour(Colour(0xff718796)).withAlpha(.6f)));g.drawHorizontalLine(27,26.f,176.f);g.setColour(nd::colour(colour));g.fillEllipse(34,11,6,6);g.setFont(FontOptions(nd::number("fontSize",11.5f),Font::bold));g.drawFittedText(fxDefinitions()[(size_t)entry.type].name.toUpperCase(),{48,0,123,28},Justification::centredLeft,1);
  g.setColour(nd::colour(nd::colour(Colour(0xff111e28))));g.drawVerticalLine(176,4.f,(float)getHeight()-4);g.drawVerticalLine(getWidth()-219,4.f,(float)getHeight()-4);g.setColour(nd::colour(nd::colour(Colour(0xff7c91a1)).withAlpha(.32f)));g.drawVerticalLine(177,4.f,(float)getHeight()-4);g.drawVerticalLine(getWidth()-218,4.f,(float)getHeight()-4);g.drawHorizontalLine(1,27.f,(float)getWidth()-27);g.setColour(nd::colour(Colours::black.withAlpha(.5f)));g.drawHorizontalLine(getHeight()-2,27.f,(float)getWidth()-27);
  symbol(g,colour.withAlpha(.65f));screw(g,13,16);screw(g,13,(float)getHeight()-16);screw(g,(float)getWidth()-13,(float)getHeight()-16);g.setColour(nd::colour(nd::colour(Colour(0xff111d27))));g.drawRoundedRectangle(r,nd::number("radius",4),1);UiStyle::maskCorners(g,getLocalBounds().toFloat(),nd::colour(Colour(0xff0a1118)));
 }

