 void listBoxItemDoubleClicked(int row,const juce::MouseEvent&)override{if(row>=0&&row<getNumRows()){juce::String id=fxId(entries[(size_t)row].slot,"enabled");p.set(id,1-p.value(id));}}
 juce::var getDragSourceDescription(const juce::SparseSet<int>& selected)override{if(selected.isEmpty())return {};int index=selected[0];if(index<0||index>=getNumRows())return {};auto* d=new juce::DynamicObject();d->setProperty("kind","NoCTRL.FxOrder");d->setProperty("slot",entries[(size_t)index].slot);d->setProperty("bus",bus);d->setProperty("instance",juce::String::toHexString((juce::int64)(intptr_t)&p));return juce::var(d);}
 void loadIR(int slot){using namespace juce;chooser=std::make_unique<FileChooser>("Load convolution impulse response",File::getSpecialLocation(File::userDocumentsDirectory),"*.wav;*.aif;*.aiff;*.flac");auto safe=Component::SafePointer<FxPage>(this);chooser->launchAsync(FileBrowserComponent::openMode|FileBrowserComponent::canSelectFiles,[safe,slot](const FileChooser& picker){if(!safe||picker.getResult()==File())return;String error;if(!safe->p.loadFxIR(slot,picker.getResult(),error))AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Impulse response",error);});}
 void refresh(){using namespace juce;seen=p.rack();connectionTabs.clear();if(bus>=3&&!seen->connections[bus-3])bus=0;int tabX=0;for(int r=0;r<10;++r)if(!mainRackOnly&&seen->connections[r]){auto* tab=connectionTabs.add(new ConnectionRackTab(p,r+3));OscModernTheme::styleTab(*tab);tab->getProperties().set("roundedModTab",true);tab->setComponentID("fx-connection-tab:"+String(r+3));connectionTabsContent.addAndMakeVisible(tab);tab->setBounds(tabX,0,170,29);tabX+=174;tab->setToggleState(bus==r+3,dontSendNotification);tab->onClick=[this,r]{selectBus(r+3);};}connectionTabsContent.setSize(jmax(1,tabX),29);connectionTabsView.setVisible(!connectionTabs.isEmpty());imported.setVisible(!mainRackOnly&&connectionTabs.isEmpty());int scroll=viewport.getViewPositionY();rows.clear();entries.clear();rowTops.clear();int top=0;for(auto& e:seen->entries)if(e.bus==bus){auto* row=rows.add(new FxRow(p,e));content.addAndMakeVisible(row);rowTops.push_back(top);int height=FxRow::preferredHeight(e.type);row->setBounds(6,top,934,height);top+=height+4;auto safe=Component::SafePointer<FxPage>(this);row->onLoadIR=[safe](int slot){if(safe)safe->loadIR(slot);};entries.push_back(e);}content.showHint=entries.empty();content.setSize(946,jmax(viewport.getHeight(),top+124));content.repaint();viewport.setViewPosition(0,scroll);main.setToggleState(bus==0,dontSendNotification);bus1.setToggleState(bus==1,dontSendNotification);bus2.setToggleState(bus==2,dontSendNotification);legacy.setVisible(!mainRackOnly&&bus==0);order.updateContent();resized();repaint();}
 void selectBus(int next){if(mainRackOnly&&next!=0)return;bus=next;refresh();viewport.setViewPosition(0,0);}
 void paintOverChildren(juce::Graphics& g)override{nd::Scope suitScope("rack");UiStyle::maskCorners(g,juce::Rectangle<float>(0,0,235,(float)juce::jmax(390,getHeight())));}
public:
 void selectConnectionRack(int next){selectBus(next);}
 explicit FxPage(SynthProcessor& processor,bool onlyMain=false):p(processor),mainRackOnly(onlyMain||processor.effectOnly){using namespace juce;setComponentID("fx-page");setLookAndFeel(&theme);theme.attach(*this);setOpaque(true);addAndMakeVisible(connectionTabsView);connectionTabsView.setViewedComponent(&connectionTabsContent,false);connectionTabsView.setScrollBarsShown(false,true);connectionTabsView.setScrollBarThickness(5);for(auto* button:{&main,&bus1,&bus2,&add,&imported,&libraryButton})addAndMakeVisible(button);for(auto* button:{&main,&bus1,&bus2}){OscModernTheme::styleTab(*button);button->getProperties().set("roundedModTab",true);}main.setBounds(0,0,75,29);bus1.setBounds(79,0,76,29);bus2.setBounds(159,0,76,29);add.setBounds(0,34,65,28);libraryButton.setBounds(69,34,166,28);libraryButton.setComponentID("fx-library-open");libraryButton.onClick=[this]{libraryWindows.add(AssetBrowser::open(p,bus,AssetKind::Fx,this));};imported.setBounds(988,0,220,29);imported.setComponentID("imported-fx-info");imported.onClick=[this]{auto assets=std::atomic_load(&p.importedAssets);if(assets&&assets->expansion)juce::AlertWindow::showMessageBoxAsync(juce::MessageBoxIconType::InfoIcon,"Imported FX processing",describeImportedFx(*assets->expansion));};main.onClick=[this]{selectBus(0);};bus1.onClick=[this]{selectBus(1);};bus2.onClick=[this]{selectBus(2);};addAndMakeVisible(legacy);legacy.setBounds(252,0,262,29);legacy.setTooltip("Enabled: the existing synth/import FX run before this Main rack. Disable for rack-only processing. Direct bypasses Main FX.");if(!mainRackOnly)legacyLink=std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.state,"fxLegacyMain",legacy);addAndMakeVisible(viewport);viewport.setBounds(244,36,964,354);viewport.setViewedComponent(&content,false);viewport.setScrollBarsShown(true,false);addAndMakeVisible(order);order.setModel(this);order.setBounds(0,68,235,322);order.setRowHeight(30);order.setColour(ListBox::backgroundColourId,nd::colour(Colour(0xff101c26)));order.setColour(ListBox::outlineColourId,nd::colour(Colour(0xff486074)));order.setOutlineThickness(1);order.setComponentID("fx-rack-order");add.onClick=[this]{PopupMenu menu;auto& defs=fxDefinitions();for(int i=0;i<(int)defs.size();++i)menu.addItem(i+1,defs[(size_t)i].name);auto safe=Component::SafePointer<FxPage>(this);menu.showMenuAsync(PopupMenu::Options().withTargetComponent(&add),[safe](int selected){if(!safe||selected==0)return;if(safe->p.addFx(safe->bus,selected-1)<0)AlertWindow::showMessageBoxAsync(MessageBoxIconType::InfoIcon,"FX rack","The rack supports 64 simultaneous effect instances.");});};if(mainRackOnly){main.setVisible(false);bus1.setVisible(false);bus2.setVisible(false);legacy.setVisible(false);imported.setVisible(false);}refresh();startTimerHz(25);}
 void resized()override{int tabsX=bus==0?520:244;connectionTabsView.setBounds(tabsX,0,1208-tabsX,34);int h=juce::jmax(390,getHeight());int rackTop=mainRackOnly?0:36,listTop=mainRackOnly?34:68;viewport.setBounds(244,rackTop,964,h-rackTop);order.setBounds(0,listTop,235,h-listTop);if(mainRackOnly){add.setBounds(0,0,65,28);libraryButton.setBounds(69,0,166,28);}content.setSize(946,juce::jmax(viewport.getHeight(),rows.isEmpty()?0:rowTops.back()+rows.getLast()->getHeight()+128));}
 ~FxPage()override{for(auto& window:libraryWindows)if(window)delete window.getComponent();stopTimer();order.setModel(nullptr);rows.clear();setLookAndFeel(nullptr);}
 bool isInterestedInDragSource(const SourceDetails& source)override{return source.description.getProperty("kind",{}).toString()=="NoCTRL.FxOrder"&&(int)source.description.getProperty("bus",-1)==bus&&source.description.getProperty("instance",{}).toString()==juce::String::toHexString((juce::int64)(intptr_t)&p);}
 void itemDropped(const SourceDetails& source)override{if(!isInterestedInDragSource(source)||!order.getBounds().contains(source.localPosition)||entries.empty())return;int index=juce::jlimit(0,(int)entries.size()-1,(source.localPosition.y-order.getY()+order.getViewport()->getViewPositionY())/30);p.moveFxTo((int)source.description["slot"],index);refresh();}
 void paint(juce::Graphics& g)override{nd::Scope suitScope("rack");using namespace juce;g.fillAll(UiStyle::canvas());UiStyle::card(g,Rectangle<float>(0,0,235,(float)jmax(390,getHeight())));if(entries.empty()){g.setColour(nd::colour(nd::colour(Colour(0xff91a7b9))));g.setFont(FontOptions(nd::number("fontSize",15)));g.drawText("Add an effect with + FX",Rectangle<int>(244,120,946,40),Justification::centred);g.setFont(FontOptions(nd::number("fontSize",11)));g.drawText(mainRackOnly?"Input > FX > Output":bus>=3?connectionRackName(bus)+" / Shared stereo insert before filter":bus==0?"Main rack > Main fader. Direct stays clean.":"Bus rack > Bus fader > selected bus output.",Rectangle<int>(244,164,946,25),Justification::centred);}}
